window.registerChapter({"num": 128, "title": "Salmonella Infections", "group": "Bacterial infections", "pdf_start": 794, "pdf_end": 806, "printed_start": 780, "printed_end": 792, "features": ["Fever", "Cough", "Diarrhea", "Hepatosplenomegaly", "Meningitis", "Arthritis / bone pain", "Abscess / soft tissue", "Sepsis / shock", "Anemia / hemolysis", "Immunocompromised host", "Animal exposure", "Water exposure", "Travel / endemic setting"], "pillars": [{"label": "Etiology and transmission", "text": "Salmonella bacteria are gram-negative bacilli in the Enterobacterales order. Current taxonomy recognizes 3 Salmonella species: S enterica with 6 subspecies, Salmonella bongori, and Salmonella subterranea.", "pdf_page": 794, "printed_page": 780}, {"label": "Clinical recognition", "text": "Nontyphoidal Salmonella Infection Nontyphoidal Salmonella (NTS) infection is associated with a spectrum of illness ranging from asymptomatic gastrointestinal tract carriage to gastroenteritis, urinary tract infection, bacteremia, and focal infections, including meningitis, brain abscess, and osteomyelitis (to which people with sickle cell anemia are predisposed). The most common illness associated with NTS infection is gastroenteritis, with manifestations of diarrhea, abdominal cramps, and fever.", "pdf_page": 794, "printed_page": 780}, {"label": "Diagnostic workup", "text": "Isolation of Salmonella from cultures of stool, blood, urine, bile (including duodenal fluid containing bile), and material from foci of infection is diagnostic. NTS gastroenteritis is diagnosed by stool culture or molecular testing; stool cultures should be obtained in all children with bloody diarrhea, or unexplained persistent or severe diarrhea.", "pdf_page": 795, "printed_page": 781}, {"label": "Treatment in the atlas", "text": "Nontyphoidal Salmonella Infection • Antimicrobial therapy usually is not indicated for patients with either asymptomatic infection or uncomplicated gastroenteritis caused by NTS serovars, because therapy does not shorten the duration of diarrheal disease, can prolong duration of fecal shedding, and increases symptomatic relapse rate.", "pdf_page": 796, "printed_page": 782}, {"label": "Prevention and infection control", "text": "In addition to standard precautions, contact precautions should be used for diapered and incontinent children for the duration of illness. In children with enteric fever, precautions should be continued until culture results are negative for 3 consecutive stool specimens obtained at least 48 hours after cessation of antimicrobial therapy.", "pdf_page": 798, "printed_page": 784}], "figures": [{"path": "figures/ch128_p0801_01.jpg", "caption": "Image 128.1 Scanning electron micrograph of Salmonella Typhimurium invading a human epithelial cell. Courtesy of National Institute of Allergy and Infectious Diseases.", "caption_matched": true, "pdf_page": 801, "printed_page": 787, "chapter": 128}, {"path": "figures/ch128_p0801_02.jpg", "caption": "Image 128.2 Salmonella bacteria (pink), a common cause of foodborne disease, invade a human epithelial cell (yellow). Courtesy of National Institute of Allergy and Infectious Diseases.", "caption_matched": true, "pdf_page": 801, "printed_page": 787, "chapter": 128}, {"path": "figures/ch128_p0801_03.jpg", "caption": "Image 128.3 A young child with sickle cell disease and Salmonella sepsis with swelling of the hands. Probable diagnosis: acute sickle cell dactylitis with septicemia. Copyright Martin G. Myers, MD.", "caption_matched": true, "pdf_page": 801, "printed_page": 787, "chapter": 128}, {"path": "figures/ch128_p0801_04.jpg", "caption": "Image 128.4 A young child with sickle cell dactylitis of the foot and Salmonella sepsis. This is the same patient as in Image 128.3. Copyright Martin G. Myers, MD.", "caption_matched": true, "pdf_page": 801, "printed_page": 787, "chapter": 128}, {"path": "figures/ch128_p0802_01.jpg", "caption": "Image 128.5 Rose spots on the chest of a patient with typhoid fever caused by the bacterium Salmonella serovar Typhi. Symptoms of typhoid fever may include a sustained fever as high as 39.4°C to 40.0°C (103°F–104°F), weakness, stomach pains, headache, and loss of appetite. In some cases, patients have a rash of flat, rose-colored spots. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 802, "printed_page": 788, "chapter": 128}, {"path": "figures/ch128_p0802_02.jpg", "caption": "Image 128.6 Typhoid fever cholecystitis with an ulceration and perforation of the gallbladder into the jejunum. Salmonella serovar Typhi, the bacterium responsible for causing typhoid fever, has a preference for the gallbladder and, if present, will colonize the surface of gallstones, which is how people become long-term carriers of the disease. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 802, "printed_page": 788, "chapter": 128}, {"path": "figures/ch128_p0802_03.jpg", "caption": "Image 128.7 Histopathologic features of the gallbladder in a case of typhoid fever. Salmonella serovar Typhi, the bacterium responsible for causing typhoid fever, has a preference for the gallbladder and, if present, will colonize the surface of gallstones, which is how people become long-term carriers of the disease. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 802, "printed_page": 788, "chapter": 128}, {"path": "figures/ch128_p0802_04.jpg", "caption": "Image 128.8 Osteomyelitis caused by Salmonella infection of the distal tibia.", "caption_matched": true, "pdf_page": 802, "printed_page": 788, "chapter": 128}, {"path": "figures/ch128_p0803_01.jpg", "caption": "Image 128.9 Gram stain of Salmonella species. Courtesy of Rita Yee, MT(ASCP)SM.", "caption_matched": true, "pdf_page": 803, "printed_page": 789, "chapter": 128}, {"path": "figures/ch128_p0803_02.jpg", "caption": "Image 128.10 A computed tomographic scan showing a large brain abscess in the posterior parietal region as a complication of Salmonella meningitis in a neonate.", "caption_matched": true, "pdf_page": 803, "printed_page": 789, "chapter": 128}, {"path": "figures/ch128_p0803_03.jpg", "caption": "Image 128.11 Histopathologic changes in brain tissue caused by Salmonella serovar Typhi meningitis. Salmonella septicemia has been associated with subsequent infection of virtually every organ system, and the nervous system is no exception. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 803, "printed_page": 789, "chapter": 128}, {"path": "figures/ch128_p0803_04.jpg", "caption": "Image 128.12 Salmonella pneumonia with empyema in a 3-year-old girl who had congenital neutropenia and required chest tube drainage and prolonged antibiotic treatment to control extensive pneumonia caused by a nontyphoidal Salmonella species. Courtesy of Edgar O. Ledbetter, MD, FAAP.", "caption_matched": true, "pdf_page": 803, "printed_page": 789, "chapter": 128}, {"path": "figures/ch128_p0804_01.jpg", "caption": "Image 128.14 Number of infections diagnosed via culture or culture-independent diagnostic tests (CIDTs), by pathogen, year, and culture status—10 U.S. sites, Foodborne Diseases Active Surveillance Network,* 2016–2019.† *Data collected from laboratories in Connecticut, Georgia, Maryland, Minnesota, New Mexico, Oregon, Tennessee, and selected counties in California, Colorado, and New York. †Data for 2019 are preliminary. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 804, "printed_page": 790, "chapter": 128}, {"path": "figures/ch128_p0804_02.jpg", "caption": "Image 128.13 This image depicts the colonial growth pattern displayed by Salmonella enterica subspecies arizonae grown on blood agar, also known as S arizonae or Arizona hinshawii. Salmonella species are gram-negative, aerobic, rod-shaped, zoonotic bacteria that can infect people, birds, reptiles, and other animals. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 804, "printed_page": 790, "chapter": 128}, {"path": "figures/ch128_p0805_01.jpg", "caption": "Image 128.16 Paratyphoid fever cases reported to National Typhoid and Paratyphoid Fever Surveillance, by jurisdiction, 2020 (n 5 48). Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 805, "printed_page": 791, "chapter": 128}, {"path": "figures/ch128_p0805_02.jpg", "caption": "Image 128.15 Typhoid fever cases reported to National Typhoid and Paratyphoid Fever Surveillance, by jurisdiction, 2020 (n 5 157). Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 805, "printed_page": 791, "chapter": 128}, {"path": "figures/ch128_p0806_01.jpg", "caption": "Image 128.19 Foodborne diseases, infections by year. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 806, "printed_page": 792, "chapter": 128}, {"path": "figures/ch128_p0806_02.jpg", "caption": "Image 128.17 African dwarf frog. Salmonella infection can be acquired through contact with reptiles and amphibians in homes, petting zoos, parks, child care facilities, and other locations. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 806, "printed_page": 792, "chapter": 128}, {"path": "figures/ch128_p0806_03.jpg", "caption": "Image 128.18 Turtles carry Salmonella. The sale of turtles ,10 cm (4 inches) in length has been banned in the United States since 1975. The ban by the U.S. Food and Drug Administration has prevented an estimated 100,000 cases of salmonellosis annually in children. Courtesy of Centers for Disease Control and Prevention/James Gathany.", "caption_matched": true, "pdf_page": 806, "printed_page": 792, "chapter": 128}], "tables": [{"pdf_page": 799, "printed_page": 785, "markdown": "|Typhoid<br>Vaccine|Type|Route|Minimum Age<br>of Receipt|No. of Dosesa|Booster<br>Frequency, y|\n|---|---|---|---|---|---|\n|Ty21a|Live attenuated|Oral|6 years|4|5|\n|ViCPS|Polysaccharide|Intramuscular|2 years|1|2|\n\n", "path": "tables/ch128_p0799_1.jpg", "orientation_normalized": false}], "reader_html": "<section><h2>Clinical Manifestations</h2><p>Nontyphoidal Salmonella Infection Nontyphoidal Salmonella (NTS) infection is associated with a spectrum of illness ranging from asymptomatic gastrointestinal tract carriage to gastroenteritis, urinary tract infection, bacteremia, and focal infections, including meningitis, brain abscess, and osteomyelitis (to which people with sickle cell anemia are predisposed). The most common illness associated with NTS infection is gastroenteritis, with manifestations of diarrhea, abdominal cramps, and fever. The site of infection usually is the distal small intestine and colon. Sustained or intermittent bacteremia can occur, and focal infections are recognized in up to 10% of patients with NTS bacteremia. In the United States, the incidence of invasive NTS is highest among infants. Certain NTS serovars (eg, Dublin, Choleraesuis), although rare, are more likely to result in invasive infection than gastroenteritis. Invasive NTS disease in infants and toddlers, manifesting as severe clinical illness and accompanied by high case fatality rates, is prevalent in many parts of sub-Saharan Africa. Salmonella Typhimurium, Salmonella Enteritidis, and Salmonella I:4,[5],12:i:- (and, to a lesser extent, Salmonella Dublin) are the most frequent NTS serovars isolated from blood and cerebrospinal fluid. Severe anemia, malaria, HIV, and malnutrition are known risk factors that contribute to the high case fatality rate (10%–30%). However, whole genome sequencing has revealed that most of the Salmonella Typhimurium and Salmonella I:4,[5],12:i:- isolates from infants and toddlers with invasive NTS disease in sub-Saharan Africa exhibit genomic degradation that renders them distinct from NTS associated with gastroenteritis in North America and Europe.</p><small class='source'>Printed p. 780 · PDF p. 794</small><p>Enteric Fever Salmonella enterica serovars Typhi, Paratyphi A, Paratyphi B, and Paratyphi C (which occurs rarely) can cause a protracted bacteremic illness referred to collectively as enteric fever (and as typhoid fever and paratyphoid fever). In older children, the onset of enteric fever typically is gradual, with manifestations such as fever, constitutional symptoms (eg, headache, malaise, anorexia, cough, and lethargy), abdominal pain, hepatomegaly, splenomegaly, dactylitis, and rose spots (visible in approximately 30% of patients). Change in mental status and shock may ensue. Myocarditis or endocarditis occur rarely. In infants and toddlers, invasive infection with enteric fever serovars can manifest as a mild, nondescript febrile illness accompanied by self-limited bacteremia or as an invasive infection in association with more severe clinical symptoms and signs, sustained bacteremia, and meningitis. Diarrhea (resembling pea soup) or constipation can be early features. Intestinal perforations or hemorrhage occur in up to 10% of hospitalized adults and children with enteric fever. Prolonged untreated typhoid increases the risk for intestinal perforations. Relative bradycardia (pulse rate slower than would be expected for a given body temperature) has been considered a common feature of typhoid fever in adults but in children is neither a discriminating feature in the assessment of a febrile child from an area where enteric fever is endemic nor a feature of the disease per se. Chronic carriage of S Typhi (excretion longer than 1 year) following acute typhoid infection is associated with cholelithiasis, increased age, and female sex.1 Chronic carriage in children is uncommon.</p><small class='source'>Printed p. 780 · PDF p. 794</small></section><section><h2>Etiology</h2><p>Salmonella bacteria are gram-negative bacilli in the Enterobacterales order. Current taxonomy recognizes 3 Salmonella species: S enterica with 6 subspecies, Salmonella bongori, and Salmonella subterranea. S enterica subspecies enterica (also called subspecies I) is responsible for most infections in humans and other warm-blooded animals; the other S enterica subspecies and S bongori are usually isolated from cold-blooded animals. More than 2,600 Salmonella serovars have been described. During 2017–2021, the most commonly reported human clinical isolates in the United States were Salmonella serovars Enteritidis, Newport, Typhimurium, and Javiana; these serovars accounted for approximately 45% of all human clinical Salmonella isolates in the United States during this period (www.cdc.gov/ncezid/dfwed/ BEAM-dashboard.html). S Typhi belongs to O serogroup 9, along with many other common serovars including Enteritidis and Dublin. The relative prevalence of serovars varies by country, state, and county.</p><small class='source'>Printed p. 780 · PDF p. 794</small></section><section><h2>Epidemiology</h2><p>Nontyphoidal Salmonella Infection Every year, NTS organisms are among the most common causes of laboratory-confirmed cases of enteric disease reported to the U.S. Foodborne Diseases Active Surveillance Network (wwwn. cdc.gov/foodnetfast). The incidence of NTS infection is highest in children younger than 4 years. In the United States, rates of invasive infections and mortality are higher in infants, elderly people, and people with hemoglobinopathies (including sickle cell disease) and immunocompromising conditions (eg, malignant neoplasms, HIV infection). Most reported cases are sporadic, but widespread outbreaks, including health care-associated and institutional outbreaks, have been reported.</p><small class='source'>Printed p. 781 · PDF p. 795</small><p>The incidence of foodborne cases of NTS gastroenteritis ranged from 16.6 to 19.6 per 100,000 in the period of 2015–2019, but fell to 13.3 per 100,000 in 2020. The incidence of diarrheal infections attributable to Campylobacter species, Shiga toxin-producing Escherichia coli, and Shigella species also decreased notably in 2020, likely as a result of the COVID-19 pandemic (wwwn.cdc. gov/foodnetfast and www.cdc.gov/foodnet/ reports/prelim-data-intro-2018.html).</p><small class='source'>Printed p. 781 · PDF p. 795</small><p>The principal reservoirs for NTS organisms include birds, mammals, reptiles, and amphibians. The major food vehicles of transmission to humans in industrialized countries include seeded vegetables and other produce as well as food of animal origin (such as poultry, beef, pork, eggs, and dairy products). Multiple other food vehicles (eg, peanut butter, frozen pot pies, powdered infant formula, cereal, and bakery products) have also been implicated in outbreaks in the United States and Europe. Other modes of transmission include ingestion of contaminated water or close contact with infected animals, mainly poultry (eg, chicks, chickens, ducks), reptiles or amphibians (eg, pet turtles, iguanas, geckos, bearded dragons, lizards, snakes, frogs, toads, newts, salamanders), and rodents (eg, hamsters, mice, guinea pigs) or other mammals (eg, hedgehogs). Reptiles and amphibians that live in tanks or aquariums can contaminate the water with bacteria, which can spread to people. Small turtles with a shell length of less than 4 inches are a well-known source of Salmonella infections. Because of this risk, the U.S. Food and Drug Administration (FDA) has banned the interstate sale and distribution of these turtles since 1975. Animal-derived pet foods and treats have been linked to Salmonella infections as well, especially in young children.</p><small class='source'>Printed p. 781 · PDF p. 795</small><p>A risk of transmission to others persists for as long as an infected person sheds NTS organisms. Twelve weeks after infection with the most common NTS serovars, approximately 45% of children younger than 5 years shed organisms, compared with 5% of older children and adults; antimicrobial therapy can prolong shedding. Approximately 1% of adults continue to shed NTS organisms for more than 1 year.</p><small class='source'>Printed p. 781 · PDF p. 795</small><p>Enteric Fever Although typhoid fever (approximately 300–400 cases annually) and paratyphoid fever (approximately 100 cases annually) are uncommon in the United States, these infections are highly endemic in many resource-limited countries, particularly in Asia. Consequently, most typhoid fever infections in U.S. residents are acquired during international travel. Unlike NTS serovars, the enteric fever serovars (S Typhi, S Paratyphi A, S Paratyphi B, and S Paratyphi C) are restricted to human hosts, in whom they cause both clinical and subclinical infections. Chronic human S Typhi carriers (mostly involving chronic infection of the gallbladder in persons with cholelithiasis but occasionally involving infection of the urinary tract) constitute the long-term reservoir of typhoidal Salmonella in areas with endemic disease. Infection with enteric fever serovars implies ingestion of a food or water vehicle contaminated by a chronic carrier or a person with acute clinical or subclinical typhoidal Salmonella infection.</p><small class='source'>Printed p. 781 · PDF p. 795</small><p>The incubation period for NTS gastroenteritis usually is 6 to 48 hours, but incubation periods of a week or more have been reported. For enteric fever, the incubation period usually is 7 to 14 days (range 3–60 days).</p><small class='source'>Printed p. 781 · PDF p. 795</small></section><section><h2>Diagnostic Tests</h2><p>Isolation of Salmonella from cultures of stool, blood, urine, bile (including duodenal fluid containing bile), and material from foci of infection is diagnostic. NTS gastroenteritis is diagnosed by stool culture or molecular testing; stool cultures should be obtained in all children with bloody diarrhea, or unexplained persistent or severe diarrhea. To evaluate for enteric fever, blood cultures (positive in 60% of patients with enteric fever) and stool cultures (positive in up to 30%) should be obtained for all children who present with unexplained fever after travel to resource-limited countries or contact with someone who has traveled internationally. In addition, blood cultures should be considered for patients at risk of severe illness (eg, age &lt;3 months, those who are immunocompromised or have hemolytic anemia) and in patients with evidence of disseminated infection, bacteremia, or septicemia. Optimal recovery of Salmonella from stool is achieved with the use of enrichment broth and multiple selective agar plate media. Definitive identification requires confirmation by phenotypic methods (biochemical profiling and preliminary agglutination with high-quality typing sera, if available, in the hospital or state laboratory), molecular methods (such as polymerase chain reaction [PCR]-based assays), or mass spectrometry of cellular components and O serogroup determination. Serovar determination using validated antisera to identify O group and phase 1 and 2 flagella (H) antigens and Vi polysaccharide capsule or serotyping by whole genome sequencing are helpful for epidemiologic purposes and usually performed at public health laboratories.</p><small class='source'>Printed p. 781 · PDF p. 795</small><p>Diagnostic tests to detect Salmonella antigens by enzyme immunoassay, latex agglutination, and monoclonal antibodies have been developed, as have commercial immunoassays that detect antibodies to antigens of enteric fever serovars. These tests are especially important in areas of the world where typhoid fever is endemic.</p><small class='source'>Printed p. 782 · PDF p. 796</small><p>Several multiplex PCR platforms for detection of multiple viral, parasitic, and bacterial pathogens, including Salmonella organisms, directly in stool have been approved for diagnostic use by the FDA and are commercially available. Nevertheless, clinical microbiology laboratories should maintain culture capabilities for Salmonella species because antimicrobial susceptibility testing requires an isolate. In addition, isolates are useful for state public health laboratories to conduct genomic characterization of strains for outbreak detection and epidemiologic investigation.</p><small class='source'>Printed p. 782 · PDF p. 796</small><p>If enteric fever is suspected, multiple cultures may be needed to isolate the pathogen. Blood, bone marrow, and bile (or duodenal fluid containing bile) are the highest-yield clinical specimens for culture. Bone marrow cultures are considered the gold standard and may be positive even when blood cultures are negative. S Typhi and S Paratyphi are often not recovered from stool culture. The sensitivity of blood culture and bone marrow culture in children with enteric fever is approximately 60% and 90%, respectively. The sensitivity of a single blood culture plus culture of bile (collected from a bile-stained duodenal string) is 90% for detecting S Typhi infection in children with clinical enteric fever. Collection of large but age-appropriate blood volumes is needed to optimize recovery of organisms from blood cultures.</p><small class='source'>Printed p. 782 · PDF p. 796</small><p>The Centers for Disease Control and Prevention does not recommend using serologic tests, such as the Widal test, to diagnose acute typhoid, because these tests are difficult to interpret in populations in whom previous Salmonella infection or vaccination may result in a false-positive result. Isolate recovery remains important for guiding antimicrobial therapy for enteric fever, given that cases are increasingly caused by multidrugresistant strains. Serologic testing may be helpful for identification of chronic carriers, who often have very elevated immunoglobulin (Ig) G Vi titers. However, Vi serologic testing is not useful if the individual has received a Vi polysaccharide vaccine within the previous year.</p><small class='source'>Printed p. 782 · PDF p. 796</small></section><section><h2>Treatment</h2><p>Nontyphoidal Salmonella Infection • Antimicrobial therapy usually is not indicated for patients with either asymptomatic infection or uncomplicated gastroenteritis caused by NTS serovars, because therapy does not shorten the duration of diarrheal disease, can prolong duration of fecal shedding, and increases symptomatic relapse rate.</p><small class='source'>Printed p. 782 · PDF p. 796</small><p>• Antimicrobial therapy is recommended for gastroenteritis caused by NTS serovars in people at increased risk for invasive disease, including infants younger than 3 months and people with chronic gastrointestinal tract disease, neoplasms, hemoglobinopathies, HIV infection, or other immunocompromising conditions. It should also be considered for those experiencing severe symptoms, such as severe diarrhea or prolonged or high fever.</p><small class='source'>Printed p. 782 · PDF p. 796</small><p>• If antimicrobial therapy is initiated in patients in the United States with presumed or proven NTS gastroenteritis, a blood and a stool culture should be obtained prior to antibiotic administration and an initial dose of ceftriaxone should be given. The patient who does not appear ill or have evidence of disseminated infection can be discharged on oral azithromycin pending blood culture results. Once susceptibilities are available, ampicillin/amoxicillin or trimethoprimsulfamethoxazole (TMP-SMX) may be considered for susceptible strains. A fluoroquinolone is an alternative option. For those who appear ill or have evidence of disseminated infection, hospitalization is required.</p><small class='source'>Printed p. 783 · PDF p. 797</small><p>• For patients with bacteremia caused by NTS, evaluation for disseminated disease (meningitis, osteoarticular infection, endocarditis) should be considered. Blood cultures should be repeated until negative. Initial therapy with ceftriaxone should be administered. Transition from intravenous ceftriaxone to oral azithromycin or a fluoroquinolone to complete a 7- to 10-day course of therapy may be considered after the blood culture has cleared and focal disease has been excluded. Specific antimicrobial, route of administration, and duration of therapy will depend on antimicrobial susceptibilities, patient age and other host factors, clinical response, and geographic region and availability of antibiotics. Aminoglycosides have reduced effectiveness and are not recommended for the treatment of any invasive Salmonella infections (including those attributable to S Typhi) despite in vitro sensitivity of strains.</p><small class='source'>Printed p. 783 · PDF p. 797</small><p>• Treatment durations should be extended to 4 weeks for meningitis and 4 to 6 weeks for osteomyelitis or other focal metastatic infections. Evaluation for underlying immunodeficiency (eg, asplenia, HIV) should be considered for patients with invasive infection.</p><small class='source'>Printed p. 783 · PDF p. 797</small><p>• Antibiotic-resistant NTS strains are increasing. Ciprofloxacin-nonsusceptible strains increased from 2% in 2009 to 9% in 2020 (www.cdc. gov/drugresistance/pdf/threats-report/2019ar-threats-report-508.pdf and wwwn.cdc. gov/narmsnow/).</p><small class='source'>Printed p. 783 · PDF p. 797</small><p>Enteric Fever • Travel history and regional antibiotic resistance patterns should be carefully considered when choosing empiric antibiotic therapy for enteric fever. Most typhoid fever infections diagnosed in the United States are fluoroquinolone nonsusceptible; therefore, clinicians should not use fluoroquinolones as empiric therapy.</p><small class='source'>Printed p. 783 · PDF p. 797</small><p>• Since 2016, Pakistan has had an ongoing large epidemic of extensively drug-resistant (XDR) S Typhi disease with resistance to ceftriaxone, ampicillin, ciprofloxacin, and TMP-SMX; isolates are susceptible only to azithromycin and carbapenems.2 XDR S Typhi has spread to many regions of Pakistan, and many confirmed cases of XDR typhoid have been documented in travelers returning from Pakistan to the United States, Canada, European countries, Taiwan, and Australia. More recently, XDR S Typhi has also been reported in U.S. residents who did not travel internationally. Although the original Hyderabad, Pakistan, XDR strain was sensitive to azithromycin, some areas of South Asia have since reported S Typhi with diminished sensitivity to azithromycin. Mass vaccination with World Health Organization (WHO) prequalified Vi conjugate vaccine (Typbar-TCV, Bharat Biotech International, India) was conducted in Hyderabad, Pakistan, after which the incidence of XDR cases dropped markedly in the vaccinated population.</p><small class='source'>Printed p. 783 · PDF p. 797</small><p>• For enteric fever caused by S Typhi that is known or suspected to be multidrug resistant (but not XDR), empiric therapy with a parenteral third-generation cephalosporin or azithromycin should be initiated. Azithromycin or a carbapenem antibiotic should be considered if the patient has traveled to Pakistan or Iraq in the 30 days before symptom onset because of ceftriaxone-resistant strains in those countries. Drugs of choice, route of administration, and duration of therapy are based on susceptibility of the organism (or inferred susceptibility if this is not available), severity and site of infection, host characteristics, and clinical response. The optimal duration of therapy is unclear and depends on the antibiotic used. Most experts would treat for at least 7 to 10 days for uncomplicated disease, although in 1 trial of children with uncomplicated typhoid fever, a 5-day course of azithromycin was effective. If amoxicillin, TMP-SMX, or a fluoroquinolone are used on the basis of susceptibility testing, a 10- to 14-day course of therapy should be considered. Consultation with an expert in infectious diseases is recommended for management of severe and complicated cases.</p><small class='source'>Printed p. 783 · PDF p. 797</small><p>• Relapse of typhoidal Salmonella infection can occur in up to 17% of patients within 4 weeks and is a particular risk for immunocompromised patients, who may require longer duration of treatment as well as retreatment. Relapse rates appear to be lower in those treated with oral ciprofloxacin or azithromycin compared with patients treated with oral TMP-SMX, amoxicillin, or parenteral ceftriaxone.</p><small class='source'>Printed p. 784 · PDF p. 798</small><p>• The chronic typhoidal serovar carrier state may be eradicated by 4 weeks of oral therapy with ciprofloxacin in approximately 80% of people. High-dose parenteral ampicillin can be used if 4 weeks of oral fluoroquinolone therapy is not tolerated and if the strain is susceptible. Cholecystectomy followed by another course of antimicrobial agents may be indicated in some adults if antimicrobial therapy alone fails.</p><small class='source'>Printed p. 784 · PDF p. 798</small><p>• Corticosteroids may be beneficial in children with severe enteric fever, which is characterized by delirium, obtundation, stupor, coma, or shock. These drugs should be reserved for critically ill patients in whom relief of manifestations of toxemia may be lifesaving. The usual regimen is high-dose dexamethasone, administered intravenously at an initial dose of 3 mg/ kg, followed by 1 mg/kg, every 6 hours, for a total course of 48 hours.</p><small class='source'>Printed p. 784 · PDF p. 798</small><p>• For enteric fever caused by S Typhi acquired from overseas travel, a stool culture should be performed on all contacts who traveled with the index case(s). If results are positive, treatment of contacts should be initiated with azithromycin until susceptibilities are known (due to high likelihood of fluroquinolone nonsusceptibility) and the contact should be monitored for development of any symptoms. Asymptomatic people in the United States who had contact with the index case(s) but did not travel overseas with them should be evaluated on a case by case basis to determine necessity for culture of stool samples.</p><small class='source'>Printed p. 784 · PDF p. 798</small></section><section><h2>Infection Prevention And Control Measures In Health Care Settings</h2><p>In addition to standard precautions, contact precautions should be used for diapered and incontinent children for the duration of illness. In children with enteric fever, precautions should be continued until culture results are negative for 3 consecutive stool specimens obtained at least 48 hours after cessation of antimicrobial therapy. For XDR typhoid, contact precautions should be used throughout the hospital stay.</p><small class='source'>Printed p. 784 · PDF p. 798</small></section><section><h2>Control Measures</h2><p>Important measures include proper food hygiene practices; treated water supplies; proper hand hygiene; adequate sanitation to dispose of human fecal waste; exclusion of infected people from handling food or providing health care; education on the risk of Salmonella infections from animal contact; prohibiting the sale of pet turtles; limiting exposure of children younger than 5 years and immunocompromised children to reptiles, amphibians, live poultry, and rodents at home, at school, and in child care and public settings; reporting cases to appropriate health authorities; and investigating outbreaks. Eggs and other foods of animal origin should be cooked thoroughly. People should not eat raw eggs or foods containing raw eggs or consume unpasteurized milk or raw milk products.3 Child Care Outbreaks of Salmonella illness in child care centers are rare but do occur. Specific strategies for controlling infection in out-of-home child care involve adherence to hygiene practices, including meticulous hand hygiene, and limiting exposure to certain animals. Animals at higher risk of causing salmonellosis, including reptiles, amphibians, and poultry, are not recommended in schools, child care settings, hospitals, or nursing homes.</p><small class='source'>Printed p. 784 · PDF p. 798</small><p>When NTS serovars are identified in a symptomatic child care attendee or staff member with enterocolitis, older children and staff members do not need to be excluded unless they are symptomatic. Stool cultures are not required for asymptomatic contacts. Likewise, children or staff members with NTS enterocolitis do not require negative culture results from stool samples; children can return to child care facilities if stools are contained in the diaper or when toilet-trained children are continent and when stool frequency becomes no more than 2 stools above that child’s normal frequency for the time the child is in the program, even if the stools remain loose.</p><small class='source'>Printed p. 784 · PDF p. 798</small><p>When S Typhi infection is identified in a child care staff member, local or state health departments should be consulted regarding regulations for length of exclusion and testing, which may vary by jurisdiction. A directory of state and territorial, city and county, and tribal health departments can be found at www.cdc.gov/publichealthgateway/ healthdirectories/index.html. Because typhoid and paratyphoid infections can be severe (with 77% of U.S. pediatric cases resulting in hospitalization), exclusion of an infected child is warranted at least until negative results for 3 stool samples obtained at least 48 hours after cessation of antimicrobial therapy for S Typhi or S Paratyphi.</p><small class='source'>Printed p. 785 · PDF p. 799</small><p>Typhoid Vaccine Two typhoid vaccines are licensed by the FDA for use in the United States: live, attenuated oral vaccine Ty21a for people 6 years or older, and the intramuscular Vi capsular polysaccharide vaccine (ViCPS) for people 2 years or older (see Table 128.1). The effectiveness of these 2 vaccines ranges from 50% to 80%, but the duration of protection differs notably between the vaccines. Vaccine is selected on the basis of age of the child, need for booster doses, and possible contraindications and reactions.</p><small class='source'>Printed p. 785 · PDF p. 799</small><p>Recommended Use In the United States, immunization is recommended only for the following people:</p><small class='source'>Printed p. 785 · PDF p. 799</small><p>• Travelers to areas where risk of exposure to S Typhi is recognized. Risk is greatest for travelers to the Indian subcontinent, South and Southeast Asia, Latin America, the Caribbean, the Middle East, Africa, and parts of Oceania (eg, Samoa, Fiji) who may have prolonged exposure to contaminated food and drink. Travelers need to be cautioned that typhoid vaccine is not a substitute for careful selection of food and drink (see www.cdc.gov/travel).</p><small class='source'>Printed p. 785 · PDF p. 799</small><p>• People with intimate exposure to a documented chronic S Typhi carrier, as occurs with continued household contact.</p><small class='source'>Printed p. 785 · PDF p. 799</small><p>• Laboratory workers with frequent or potential contact with S Typhi.</p><small class='source'>Printed p. 785 · PDF p. 799</small><p>Dosages For primary immunization, the following dosage is recommended for each vaccine:</p><small class='source'>Printed p. 785 · PDF p. 799</small><p>• Typhoid vaccine live oral Ty21a (Vivotif). Children (6 years and older) and adults should take 1 Ty21a enteric-coated capsule every other day for a total of 4 capsules. Each capsule of Ty21a should be swallowed whole (not chewed) with liquid, no warmer than 37°C (98°F), approximately 1 hour before a meal. Ty21a should be kept refrigerated, and all 4 doses must be taken to achieve maximal effectiveness. Immunization should be completed at least 1 week before possible exposure.</p><small class='source'>Printed p. 785 · PDF p. 799</small><p>• Typhoid Vi polysaccharide vaccine (Typhim Vi). Primary immunization of people 2 years and older with unconjugated ViCPS consists of one 0.5-mL (25-μg) dose administered intramuscularly. ViCPS should be administered at least 2 weeks before possible exposure.</p><small class='source'>Printed p. 785 · PDF p. 799</small><p>• Vi conjugate vaccine (not currently licensed or available in the United States). This is a typhoid conjugate vaccine that consists of the Vi capsular polysaccharide of S Typhi linked to tetanus toxoid protein that is manufactured and licensed in India (Typbar- TCV). It is the first Vi conjugate to be prequalified by the WHO. Typbar-TCV has been recommended by the WHO Scientific Advisory Group of Experts for use in infants as young as 6 months of age on the basis of results of clinical trials establishing its tolerability and immunogenicity in children 6 through 23 months of age, as well as in older children and adults. The vaccine is administered as a single intramuscular dose and provides greater protection against typhoid fever than the other available vaccines. Serum IgG Vi antibody appears to endure for several years among children living in areas with endemic infection. Mass vaccination of children in Hyderabad, Pakistan, demonstrated safety and effectiveness of Typbar-TCV in preventing typhoid attributable to the XDR S Typhi strain. Typbar-TCV is not licensed in the United States. However, if families with children younger than 2 years of age (and, hence, not able to receive the Typhim Vi vaccine) but older than 6 months are traveling to live in areas of South Asia where XDR S Typhi is circulating, parents of infants and toddlers can be advised to contact local pediatricians to have their young children vaccinated with this vaccine.</p><small class='source'>Printed p. 785 · PDF p. 799</small><p>• Protection against S Paratyphi A and S Paratyphi B. No currently available vaccine provides protection against S Paratyphi A. Results of 2 field trials suggest that Ty21a may provide partial cross protection against S Paratyphi B.</p><small class='source'>Printed p. 786 · PDF p. 800</small><p>Booster Doses In circumstances of continued or repeated exposure to S Typhi, periodic reimmunization is recommended to maintain immunity.</p><small class='source'>Printed p. 786 · PDF p. 800</small><p>Continued effectiveness for 7 years after immunization with Ty21a vaccine has been demonstrated; however, the manufacturer of Ty21a vaccine recommends reimmunization (completing the entire 4-dose series) every 5 years if continued or renewed exposure to S Typhi is expected.</p><small class='source'>Printed p. 786 · PDF p. 800</small><p>ViCPS elicits a T-lymphocyte independent antigen response that does not create immunologic memory to allow boosting of serum Vi antibody titers following an initial immunization. The manufacturer of ViCPS recommends reimmunization every 2 years if continued or renewed exposure is expected.</p><small class='source'>Printed p. 786 · PDF p. 800</small><p>Ty21a (which does not express Vi antigen) and ViCPS (which protects by stimulating serum IgG Vi antibody) mediate protection by distinct mechanisms. No data have been reported concerning use of one vaccine administered after primary immunization with the other.</p><small class='source'>Printed p. 786 · PDF p. 800</small><p>Adverse Events Ty21a vaccine is very well tolerated, but mild adverse reactions may occur; these include abdominal pain, nausea, diarrhea, vomiting, fever, headache, and rash or urticaria. Reported adverse reactions to ViCPS also are minimal and include fever, headache, malaise, myalgia, and local reaction of tenderness and pain, erythema, or induration of 1 cm or greater.</p><small class='source'>Printed p. 786 · PDF p. 800</small><p>Precautions and Contraindications A contraindication to administration of ViCPS vaccine is a history of hypersensitivity to any component of the vaccine. No safety data have been reported for typhoid vaccines in pregnant people. Ty21a vaccine is a live attenuated vaccine and should not be administered to immunocompromised people, including people known to be infected with HIV, pregnant people, or people with a phagocytic cell defect or chronic granulomatous disease.4 The intramuscular ViCPS may be an alternative, although the expected immune response may not be achieved in some hosts. Ty21a should not be administered during acute febrile illness or gastrointestinal tract illness. Antimalarial drugs mefloquine and chloroquine and the combination antimalarials atovaquone/ proguanil and pyrimethamine/sulfadoxine, at doses used for prophylaxis, can be administered with Ty21a. The manufacturer advises that other antimalarial agents be administered at least 3 days after the last dose of Ty21a.5 Antimicrobial agents should be avoided from 3 days before the first dose through 3 days after the last dose of Ty21a.</p><small class='source'>Printed p. 786 · PDF p. 800</small><p>Public Health Reporting Notification of public health authorities, sending isolates (or specimens), and determination of serovar are of primary importance in detection and investigation of outbreaks.</p><small class='source'>Printed p. 786 · PDF p. 800</small></section><h2>Original tables</h2><figure><img loading='lazy' src='tables/ch128_p0799_1.jpg' alt='Original table on printed page 785'><figcaption>Original table · printed p. 785</figcaption></figure><h2>Visual atlas</h2><figure><a href='figures/ch128_p0801_01.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0801_01.jpg' alt='Image 128.1 Scanning electron micrograph of Salmonella Typhimurium invading a human epithelial cell. Courtesy of National Institute of Allergy and Infectious Diseases.'></a><figcaption>Image 128.1 Scanning electron micrograph of Salmonella Typhimurium invading a human epithelial cell. Courtesy of National Institute of Allergy and Infectious Diseases.<br><small>Printed p. 787 · PDF p. 801</small></figcaption></figure><figure><a href='figures/ch128_p0801_02.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0801_02.jpg' alt='Image 128.2 Salmonella bacteria (pink), a common cause of foodborne disease, invade a human epithelial cell (yellow). Courtesy of National Institute of Allergy and Infectious Diseases.'></a><figcaption>Image 128.2 Salmonella bacteria (pink), a common cause of foodborne disease, invade a human epithelial cell (yellow). Courtesy of National Institute of Allergy and Infectious Diseases.<br><small>Printed p. 787 · PDF p. 801</small></figcaption></figure><figure><a href='figures/ch128_p0801_03.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0801_03.jpg' alt='Image 128.3 A young child with sickle cell disease and Salmonella sepsis with swelling of the hands. Probable diagnosis: acute sickle cell dactylitis with septicemia. Copyright Martin G. Myers, MD.'></a><figcaption>Image 128.3 A young child with sickle cell disease and Salmonella sepsis with swelling of the hands. Probable diagnosis: acute sickle cell dactylitis with septicemia. Copyright Martin G. Myers, MD.<br><small>Printed p. 787 · PDF p. 801</small></figcaption></figure><figure><a href='figures/ch128_p0801_04.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0801_04.jpg' alt='Image 128.4 A young child with sickle cell dactylitis of the foot and Salmonella sepsis. This is the same patient as in Image 128.3. Copyright Martin G. Myers, MD.'></a><figcaption>Image 128.4 A young child with sickle cell dactylitis of the foot and Salmonella sepsis. This is the same patient as in Image 128.3. Copyright Martin G. Myers, MD.<br><small>Printed p. 787 · PDF p. 801</small></figcaption></figure><figure><a href='figures/ch128_p0802_01.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0802_01.jpg' alt='Image 128.5 Rose spots on the chest of a patient with typhoid fever caused by the bacterium Salmonella serovar Typhi. Symptoms of typhoid fever may include a sustained fever as high as 39.4°C to 40.0°C (103°F–104°F), weakness, stomach pains, headache, and loss of appetite. In some cases, patients have a rash of flat, rose-colored spots. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 128.5 Rose spots on the chest of a patient with typhoid fever caused by the bacterium Salmonella serovar Typhi. Symptoms of typhoid fever may include a sustained fever as high as 39.4°C to 40.0°C (103°F–104°F), weakness, stomach pains, headache, and loss of appetite. In some cases, patients have a rash of flat, rose-colored spots. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 788 · PDF p. 802</small></figcaption></figure><figure><a href='figures/ch128_p0802_02.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0802_02.jpg' alt='Image 128.6 Typhoid fever cholecystitis with an ulceration and perforation of the gallbladder into the jejunum. Salmonella serovar Typhi, the bacterium responsible for causing typhoid fever, has a preference for the gallbladder and, if present, will colonize the surface of gallstones, which is how people become long-term carriers of the disease. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 128.6 Typhoid fever cholecystitis with an ulceration and perforation of the gallbladder into the jejunum. Salmonella serovar Typhi, the bacterium responsible for causing typhoid fever, has a preference for the gallbladder and, if present, will colonize the surface of gallstones, which is how people become long-term carriers of the disease. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 788 · PDF p. 802</small></figcaption></figure><figure><a href='figures/ch128_p0802_03.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0802_03.jpg' alt='Image 128.7 Histopathologic features of the gallbladder in a case of typhoid fever. Salmonella serovar Typhi, the bacterium responsible for causing typhoid fever, has a preference for the gallbladder and, if present, will colonize the surface of gallstones, which is how people become long-term carriers of the disease. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 128.7 Histopathologic features of the gallbladder in a case of typhoid fever. Salmonella serovar Typhi, the bacterium responsible for causing typhoid fever, has a preference for the gallbladder and, if present, will colonize the surface of gallstones, which is how people become long-term carriers of the disease. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 788 · PDF p. 802</small></figcaption></figure><figure><a href='figures/ch128_p0802_04.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0802_04.jpg' alt='Image 128.8 Osteomyelitis caused by Salmonella infection of the distal tibia.'></a><figcaption>Image 128.8 Osteomyelitis caused by Salmonella infection of the distal tibia.<br><small>Printed p. 788 · PDF p. 802</small></figcaption></figure><figure><a href='figures/ch128_p0803_01.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0803_01.jpg' alt='Image 128.9 Gram stain of Salmonella species. Courtesy of Rita Yee, MT(ASCP)SM.'></a><figcaption>Image 128.9 Gram stain of Salmonella species. Courtesy of Rita Yee, MT(ASCP)SM.<br><small>Printed p. 789 · PDF p. 803</small></figcaption></figure><figure><a href='figures/ch128_p0803_02.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0803_02.jpg' alt='Image 128.10 A computed tomographic scan showing a large brain abscess in the posterior parietal region as a complication of Salmonella meningitis in a neonate.'></a><figcaption>Image 128.10 A computed tomographic scan showing a large brain abscess in the posterior parietal region as a complication of Salmonella meningitis in a neonate.<br><small>Printed p. 789 · PDF p. 803</small></figcaption></figure><figure><a href='figures/ch128_p0803_03.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0803_03.jpg' alt='Image 128.11 Histopathologic changes in brain tissue caused by Salmonella serovar Typhi meningitis. Salmonella septicemia has been associated with subsequent infection of virtually every organ system, and the nervous system is no exception. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 128.11 Histopathologic changes in brain tissue caused by Salmonella serovar Typhi meningitis. Salmonella septicemia has been associated with subsequent infection of virtually every organ system, and the nervous system is no exception. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 789 · PDF p. 803</small></figcaption></figure><figure><a href='figures/ch128_p0803_04.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0803_04.jpg' alt='Image 128.12 Salmonella pneumonia with empyema in a 3-year-old girl who had congenital neutropenia and required chest tube drainage and prolonged antibiotic treatment to control extensive pneumonia caused by a nontyphoidal Salmonella species. Courtesy of Edgar O. Ledbetter, MD, FAAP.'></a><figcaption>Image 128.12 Salmonella pneumonia with empyema in a 3-year-old girl who had congenital neutropenia and required chest tube drainage and prolonged antibiotic treatment to control extensive pneumonia caused by a nontyphoidal Salmonella species. Courtesy of Edgar O. Ledbetter, MD, FAAP.<br><small>Printed p. 789 · PDF p. 803</small></figcaption></figure><figure><a href='figures/ch128_p0804_01.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0804_01.jpg' alt='Image 128.14 Number of infections diagnosed via culture or culture-independent diagnostic tests (CIDTs), by pathogen, year, and culture status—10 U.S. sites, Foodborne Diseases Active Surveillance Network,* 2016–2019.† *Data collected from laboratories in Connecticut, Georgia, Maryland, Minnesota, New Mexico, Oregon, Tennessee, and selected counties in California, Colorado, and New York. †Data for 2019 are preliminary. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 128.14 Number of infections diagnosed via culture or culture-independent diagnostic tests (CIDTs), by pathogen, year, and culture status—10 U.S. sites, Foodborne Diseases Active Surveillance Network,* 2016–2019.† *Data collected from laboratories in Connecticut, Georgia, Maryland, Minnesota, New Mexico, Oregon, Tennessee, and selected counties in California, Colorado, and New York. †Data for 2019 are preliminary. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 790 · PDF p. 804</small></figcaption></figure><figure><a href='figures/ch128_p0804_02.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0804_02.jpg' alt='Image 128.13 This image depicts the colonial growth pattern displayed by Salmonella enterica subspecies arizonae grown on blood agar, also known as S arizonae or Arizona hinshawii. Salmonella species are gram-negative, aerobic, rod-shaped, zoonotic bacteria that can infect people, birds, reptiles, and other animals. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 128.13 This image depicts the colonial growth pattern displayed by Salmonella enterica subspecies arizonae grown on blood agar, also known as S arizonae or Arizona hinshawii. Salmonella species are gram-negative, aerobic, rod-shaped, zoonotic bacteria that can infect people, birds, reptiles, and other animals. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 790 · PDF p. 804</small></figcaption></figure><figure><a href='figures/ch128_p0805_01.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0805_01.jpg' alt='Image 128.16 Paratyphoid fever cases reported to National Typhoid and Paratyphoid Fever Surveillance, by jurisdiction, 2020 (n 5 48). Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 128.16 Paratyphoid fever cases reported to National Typhoid and Paratyphoid Fever Surveillance, by jurisdiction, 2020 (n 5 48). Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 791 · PDF p. 805</small></figcaption></figure><figure><a href='figures/ch128_p0805_02.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0805_02.jpg' alt='Image 128.15 Typhoid fever cases reported to National Typhoid and Paratyphoid Fever Surveillance, by jurisdiction, 2020 (n 5 157). Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 128.15 Typhoid fever cases reported to National Typhoid and Paratyphoid Fever Surveillance, by jurisdiction, 2020 (n 5 157). Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 791 · PDF p. 805</small></figcaption></figure><figure><a href='figures/ch128_p0806_01.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0806_01.jpg' alt='Image 128.19 Foodborne diseases, infections by year. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 128.19 Foodborne diseases, infections by year. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 792 · PDF p. 806</small></figcaption></figure><figure><a href='figures/ch128_p0806_02.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0806_02.jpg' alt='Image 128.17 African dwarf frog. Salmonella infection can be acquired through contact with reptiles and amphibians in homes, petting zoos, parks, child care facilities, and other locations. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 128.17 African dwarf frog. Salmonella infection can be acquired through contact with reptiles and amphibians in homes, petting zoos, parks, child care facilities, and other locations. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 792 · PDF p. 806</small></figcaption></figure><figure><a href='figures/ch128_p0806_03.jpg' target='_blank'><img loading='lazy' src='figures/ch128_p0806_03.jpg' alt='Image 128.18 Turtles carry Salmonella. The sale of turtles ,10 cm (4 inches) in length has been banned in the United States since 1975. The ban by the U.S. Food and Drug Administration has prevented an estimated 100,000 cases of salmonellosis annually in children. Courtesy of Centers for Disease Control and Prevention/James Gathany.'></a><figcaption>Image 128.18 Turtles carry Salmonella. The sale of turtles ,10 cm (4 inches) in length has been banned in the United States since 1975. The ban by the U.S. Food and Drug Administration has prevented an estimated 100,000 cases of salmonellosis annually in children. Courtesy of Centers for Disease Control and Prevention/James Gathany.<br><small>Printed p. 792 · PDF p. 806</small></figcaption></figure>"});
